/**
 * Generates practice games by letting a simple rule-based player play itself.
 *
 * Usage:
 *
 * ```
 * npm run selfplay -- --games 2000
 * npm run selfplay -- --games 500 --sim ..\ps-sim-b8f23c99 --seed 7
 * ```
 *
 * Each game is a Random Battle in the real simulator, with teams generated by
 * the simulator as on the ladder. At the start of every turn the position
 * features of `lib/review/features.ts` are written to `data/selfplay.jsonl`
 * with the eventual winner, in the same format as `data/states.jsonl`.
 *
 * Why: a few hundred recorded human games are too few to learn how boosts,
 * hazards or type match-ups change the outcome. The simulator can produce
 * thousands of games for free. The games are played by a modest rule-based
 * player rather than strong humans, so they teach the scorer the mechanics but
 * not what strong play looks like. `npm run model:train-rich -- --extra
 * data/selfplay.jsonl` adds them to training only, and still measures the
 * result on human games.
 */

import { mkdir, writeFile } from 'node:fs/promises';
import { dirname, join, resolve } from 'node:path';
import { parseArgs } from 'node:util';
import { richFeatures } from '../lib/review/features';
import { chooseAction, DEFAULT_POLICY, seededRandom } from '../lib/review/policy';
import { loadBuiltSim } from '../lib/review/sim';

/** Safety cap so a stalled game cannot loop forever. */
const MAX_STEPS = 400;

async function main(): Promise<void> {
  const { values } = parseArgs({
    options: {
      games: { type: 'string', default: '1000' },
      sim: { type: 'string', default: join('..', 'ps-sim-b8f23c99') },
      seed: { type: 'string', default: '1' },
      out: { type: 'string', default: 'data/selfplay.jsonl' },
      epsilon: { type: 'string', default: String(DEFAULT_POLICY.epsilon) },
      temperature: { type: 'string', default: String(DEFAULT_POLICY.temperature) },
    },
  });
  const games = Number(values.games);
  const seed = Number(values.seed);
  if (!Number.isInteger(games) || games < 1) throw new Error('--games must be a whole number of 1 or more');
  const policy = { epsilon: Number(values.epsilon), temperature: Number(values.temperature) };

  const sim = loadBuiltSim(resolve(values.sim ?? join('..', 'ps-sim-b8f23c99')));
  const random = seededRandom(seed);
  const lines: string[] = [];
  let finished = 0;
  let p1Wins = 0;
  let totalTurns = 0;

  for (let g = 0; g < games; g++) {
    const battle = new sim.Battle({
      formatid: 'gen9randombattle',
      seed: [1, 2, 3, 4].map(() => Math.floor(random() * 0x10000)),
      p1: { name: 'P1' },
      p2: { name: 'P2' },
    });
    const id = `sp-${seed}-${g}`;
    const rows: { turn: number; f: number[] }[] = [];
    let lastTurn = -1;

    for (let step = 0; step < MAX_STEPS && !battle.ended; step++) {
      if (battle.turn !== lastTurn) {
        lastTurn = battle.turn;
        const features = richFeatures(battle);
        if (features !== null) rows.push({ turn: battle.turn, f: features.map((v) => Math.round(v * 1e4) / 1e4) });
      }
      const c1 = chooseAction(battle, 0, random, policy);
      const c2 = chooseAction(battle, 1, random, policy);
      if (c1 === null && c2 === null) break;
      try {
        if (c1 !== null) battle.choose('p1', c1);
        if (c2 !== null) battle.choose('p2', c2);
      } catch {
        break;
      }
    }

    if (!battle.ended || (battle.winner !== 'P1' && battle.winner !== 'P2')) continue;
    finished += 1;
    totalTurns += battle.turn;
    const label = battle.winner === 'P1' ? 1 : 0;
    p1Wins += label;
    for (const row of rows) lines.push(JSON.stringify({ id, turn: row.turn, f: row.f, y: label }));
    if (finished % 100 === 0) console.log(`${finished} games, ${lines.length} positions`);
  }

  const out = values.out ?? 'data/selfplay.jsonl';
  await mkdir(dirname(out), { recursive: true });
  await writeFile(out, lines.join('\n') + (lines.length > 0 ? '\n' : ''));
  console.log(
    `Wrote ${lines.length} positions from ${finished} finished games (of ${games} started) to ${out}. ` +
      `Average length ${(totalTurns / Math.max(finished, 1)).toFixed(1)} turns, player 1 won ${((p1Wins / Math.max(finished, 1)) * 100).toFixed(1)}%.`,
  );
}

main().catch((error: unknown) => {
  console.error(error);
  process.exit(1);
});
